<?php require __DIR__.'/_layout_start.php'; ?><div class="toolbar"><div><h1>Campus - Iscrizioni</h1><p class="muted">Partecipanti, lista d’attesa e presenze.</p></div><a class="btnlink" href="/admin/campus/registrations/export">Esporta CSV / Excel</a></div><div class="table-wrap"><table><thead><tr><th>Evento</th><th>Partecipante</th><th>Contatti</th><th>Azienda</th><th>Stato</th><th>Presenza</th><th>Gestione</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=htmlspecialchars($r['event_title'],ENT_QUOTES,'UTF-8')?></strong><br><span class="badge"><?=$r['audience']==='cat'?'CAT':'Aperto'?></span></td><td><?=htmlspecialchars($r['first_name'].' '.$r['last_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['email'],ENT_QUOTES,'UTF-8')?><?=!empty($r['phone'])?'<br>'.htmlspecialchars($r['phone'],ENT_QUOTES,'UTF-8'):''?></td><td><?=htmlspecialchars((string)($r['cat_company']?:$r['company']),ENT_QUOTES,'UTF-8')?></td><td><?=['registered'=>'Iscritto','confirmed'=>'Confermato','waitlist'=>'Lista d’attesa','cancelled'=>'Annullato'][$r['status']]??htmlspecialchars($r['status'],ENT_QUOTES,'UTF-8')?></td><td><?=$r['attended']===null?'—':((int)$r['attended']?'Presente':'Assente')?></td><td><form method="post" action="/admin/campus/registrations/update"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status"><option value="registered" <?=$r['status']==='registered'?'selected':''?>>Iscritto</option><option value="confirmed" <?=$r['status']==='confirmed'?'selected':''?>>Confermato</option><option value="waitlist" <?=$r['status']==='waitlist'?'selected':''?>>Lista d’attesa</option><option value="cancelled" <?=$r['status']==='cancelled'?'selected':''?>>Annullato</option></select><select name="attended"><option value="">Presenza da definire</option><option value="1" <?=$r['attended']!==null&&(int)$r['attended']===1?'selected':''?>>Presente</option><option value="0" <?=$r['attended']!==null&&(int)$r['attended']===0?'selected':''?>>Assente</option></select><button class="btn" type="submit">Salva</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/_layout_end.php'; ?>
